export function buildCardKB2(host){const pcb=board(host),input=grove(host),usbInput=usb(host),keys=KEYS.map(k=>mainKey(host,k)),reset=sideKey(host,'reset'),boot=sideKey(host,'boot'),boardElectronics=electronics(host),labelShape=outlined(...spec.label.size,.05);for(const[x,y]of spec.mountingHolesMm)hole(labelShape,x,y,1.3);labelShape.holes.push(roundedRect(2.6,5.4,1.3,{cx:39,cy:-16.5,path:new THREE.Path(),clockwise:true}));const label=solid(host.body,labelShape,.04,spec.label.position,materials.plastic(0xe2e3df,{roughness:.88}),'CardKB2 physicalfilm');label.name='CardKB2 actual supplied rearadhesivefilm carrier';label.userData={role:'physical-label-substrate',face:'back'};host.cardkb2Assembly={pcb,input,usb:usbInput,keys,reset,boot,electronics:boardElectronics,label};host.unitStickers=addStickers(host);}
